<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
using namespace std;

long long recursive(long long n, int pos, long long base[]) {
    long long total = (pos + 1LL) * (n / base[pos]);
    n %= base[pos];
    if (n == 0) return total;
    long long option1 = recursive(n, pos - 1, base);
    long long option2 = pos + 1 + recursive(base[pos] - n, pos - 1, base);
    return total + min(option1, option2);
}

int main() {
    long long a[16];
    a[0] = 1;
    for (int i = 1; i < 16; ++i) {
        a[i] = a[i - 1] * 10 + 1;
    }
    long long n;
    cin >> n;
    cout << recursive(n, 15, a) << "\n";
    return 0;
}
